/*
 * Globex iLink3 Methods
 */

/* Select the protocol version, from the preference, the
   schema the frame declares, or the capture clock in seconds
   since the unix epoch */
static int
globex_ilink3_version(uint64_t seconds, int declared)
{
    if (globex_ilink3_pref_version != GLOBEX_ILINK3_VERSION_AUTOMATIC) {
        return globex_ilink3_pref_version;
    }

    switch (declared) {
    case 9: return GLOBEX_ILINK3_VERSION_8_9;
    case 8: return GLOBEX_ILINK3_VERSION_8_8;
    case 7: return GLOBEX_ILINK3_VERSION_8_7;
    case 6: return GLOBEX_ILINK3_VERSION_8_6;
    case 5: return GLOBEX_ILINK3_VERSION_8_5;
    case 4: return GLOBEX_ILINK3_VERSION_8_4;
    case 3: return GLOBEX_ILINK3_VERSION_8_3;
    case 2: return GLOBEX_ILINK3_VERSION_8_2;
    }

    if (seconds >= GLOBEX_ILINK3_EFFECTIVE_8_9) {
        return GLOBEX_ILINK3_VERSION_8_9;
    }

    if (seconds >= GLOBEX_ILINK3_EFFECTIVE_8_8) {
        return GLOBEX_ILINK3_VERSION_8_8;
    }

    if (seconds >= GLOBEX_ILINK3_EFFECTIVE_8_7) {
        return GLOBEX_ILINK3_VERSION_8_7;
    }

    if (seconds >= GLOBEX_ILINK3_EFFECTIVE_8_6) {
        return GLOBEX_ILINK3_VERSION_8_6;
    }

    if (seconds >= GLOBEX_ILINK3_EFFECTIVE_8_5) {
        return GLOBEX_ILINK3_VERSION_8_5;
    }

    if (seconds >= GLOBEX_ILINK3_EFFECTIVE_8_4) {
        return GLOBEX_ILINK3_VERSION_8_4;
    }

    if (seconds >= GLOBEX_ILINK3_EFFECTIVE_8_3) {
        return GLOBEX_ILINK3_VERSION_8_3;
    }

    return GLOBEX_ILINK3_VERSION_8_2;
}

/* What this protocol remembers across the frames of a conversation */
typedef struct globex_ilink3_conversation {
    address initiator;
    uint32_t port;
    bool swapped;
} globex_ilink3_conversation;

/* Record of the frame's conversation, created on its first frame */
static globex_ilink3_conversation *
globex_ilink3_conversation_of(packet_info *pinfo)
{
    conversation_t *conversation = find_or_create_conversation(pinfo);
    globex_ilink3_conversation *state = (globex_ilink3_conversation *)conversation_get_proto_data(conversation, proto_globex_ilink3);

    if (state == NULL) {
        state = wmem_new0(wmem_file_scope(), globex_ilink3_conversation);
        copy_address_wmem(wmem_file_scope(), &state->initiator, &pinfo->src);
        state->port = pinfo->srcport;
        conversation_add_proto_data(conversation, proto_globex_ilink3, state);
    }

    return state;
}

/* Cap the fraction at the preferred decimal places */
static void
globex_ilink3_decimal_places(char *buf)
{
    char *point = strchr(buf, '.');

    if (point == NULL) {
        return;
    }

    unsigned places = globex_ilink3_pref_decimal_places;

    if (places >= strlen(point + 1)) {
        return;
    }

    if (places == 0) {
        *point = '\0';
        return;
    }

    point[1 + places] = '\0';
}

/* Format an implied 9 decimal place value */
static void
globex_ilink3_format_decimal_9_64(char *buf, uint64_t raw)
{
    int64_t value = (int64_t)raw;
    int64_t units = value / 1000000000;
    int64_t fraction = value % 1000000000;

    if (fraction < 0) {
        fraction = -fraction;
    }

    if (value < 0 && units == 0) {
        snprintf(buf, ITEM_LABEL_LENGTH, "-0.%09" PRId64, fraction);
    }
    else {
        snprintf(buf, ITEM_LABEL_LENGTH, "%" PRId64 ".%09" PRId64, units, fraction);
    }

    globex_ilink3_decimal_places(buf);
}

/* Format an implied 9 decimal place value */
static void
globex_ilink3_format_decimal_9_64_nullable(char *buf, uint64_t raw)
{
    int64_t value = (int64_t)raw;

    if (value == 9223372036854775807) {
        snprintf(buf, ITEM_LABEL_LENGTH, "%s", "No Value");
        return;
    }
    int64_t units = value / 1000000000;
    int64_t fraction = value % 1000000000;

    if (fraction < 0) {
        fraction = -fraction;
    }

    if (value < 0 && units == 0) {
        snprintf(buf, ITEM_LABEL_LENGTH, "-0.%09" PRId64, fraction);
    }
    else {
        snprintf(buf, ITEM_LABEL_LENGTH, "%" PRId64 ".%09" PRId64, units, fraction);
    }

    globex_ilink3_decimal_places(buf);
}

/* Format a nullable integer, the label alone for the sentinel */
static void
globex_ilink3_format_nullable_32(char *buf, uint32_t raw)
{
    uint64_t value = (uint32_t)raw;

    if (value == UINT32_MAX) {
        snprintf(buf, ITEM_LABEL_LENGTH, "%s", "No Value");
        return;
    }

    snprintf(buf, ITEM_LABEL_LENGTH, "%" PRIu64, value);
}

/* Format a nullable integer, the label alone for the sentinel */
static void
globex_ilink3_format_nullable_64(char *buf, uint64_t raw)
{
    uint64_t value = (uint64_t)raw;

    if (value == UINT64_MAX) {
        snprintf(buf, ITEM_LABEL_LENGTH, "%s", "No Value");
        return;
    }

    snprintf(buf, ITEM_LABEL_LENGTH, "%" PRIu64, value);
}

