#define GLOBEX_ILINK3_FAULT_TOLERANCE_INDICATOR_FIX         39010
#define GLOBEX_ILINK3_FAULT_TOLERANCE_INDICATOR_FILTER      "globex.ilink3.faulttoleranceindicator"
#define GLOBEX_ILINK3_FAULT_TOLERANCE_INDICATOR_TYPE        FT_UINT8
