/* Format the sentinel's label alone, an enumerated value labelled */
static void
globex_ilink3_format_liquidity_flag(char *buf, uint32_t raw)
{
    int64_t value = (int32_t)raw;

    if (value == UINT8_MAX) {
        snprintf(buf, ITEM_LABEL_LENGTH, "%s", "No Value");
        return;
    }

    snprintf(buf, ITEM_LABEL_LENGTH, "%s (%" PRId64 ")", val_to_str_const(raw, globex_ilink3_liquidity_flag_vals, "Unknown"), value);
}

