#define GLOBEX_ILINK3_RFQ_SIDE_ENCODING ENC_LITTLE_ENDIAN
#define GLOBEX_ILINK3_RFQ_SIDE_SIZE     1

static const value_string globex_ilink3_rfq_side_vals[] = {
    { 1, "Buy" },
    { 2, "Sell" },
    { 8, "Cross" },
    { 0, NULL }
};

/* Format the sentinel's label alone, an enumerated value labelled */
static void
globex_ilink3_format_rfq_side(char *buf, uint32_t raw)
{
    int64_t value = (int32_t)raw;

    if (value == UINT8_MAX) {
        snprintf(buf, ITEM_LABEL_LENGTH, "%s", "No Value");
        return;
    }

    snprintf(buf, ITEM_LABEL_LENGTH, "%s (%" PRId64 ")", val_to_str_const(raw, globex_ilink3_rfq_side_vals, "Unknown"), value);
}

