/* Format the sentinel's label alone, an enumerated value labelled */
static void
globex_ilink3_format_time_in_force(char *buf, uint32_t raw)
{
    int64_t value = (int32_t)raw;

    if (value == UINT8_MAX) {
        snprintf(buf, ITEM_LABEL_LENGTH, "%s", "No Value");
        return;
    }

    snprintf(buf, ITEM_LABEL_LENGTH, "%s (%" PRId64 ")", val_to_str_const(raw, globex_ilink3_time_in_force_vals, "Unknown"), value);
}

