/* Calculated Ccy Last Qty */
static unsigned
dissect_globex_ilink3_calculated_ccy_last_qty(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    proto_item *item = NULL;
    proto_tree *group = tree;

    if (globex_ilink3_show_structs) {
        group = proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_ilink3_calculated_ccy_last_qty, &item, "Calculated Ccy Last Qty");
    }

    unsigned start = offset;

    offset = parse_globex_ilink3_mantissa(tvb, pinfo, group, offset);
    offset = parse_globex_ilink3_exponent(tvb, pinfo, group, offset);

    proto_item_set_len(item, offset - start);

    return offset;
}

