/* Spread Leg Trade Events Groups */
static unsigned
dissect_globex_ilink3_spread_leg_trade_events_groups_v88(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    proto_item *item = NULL;
    proto_tree *group = tree;

    if (globex_ilink3_show_structs) {
        group = proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_ilink3_spread_leg_trade_events_groups_v88, &item, "Spread Leg Trade Events Groups");
    }

    unsigned start = offset;

    offset = dissect_globex_ilink3_group_size(tvb, pinfo, group, offset);

    /* Spread Leg Trade Events Group: Num In Group entries */
    uint32_t num_in_group = tvb_get_uint8(tvb, start + 2);

    for (uint32_t index = 0; index < num_in_group; index++) {
        offset = dissect_globex_ilink3_spread_leg_trade_events_group_v88(tvb, pinfo, group, offset, index + 1);
    }

    proto_item_set_len(item, offset - start);

    return offset;
}

