/* Related Sym Groups */
static unsigned
dissect_globex_ilink3_related_sym_groups_v83(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset)
{
    proto_item *item = NULL;
    proto_tree *group = tree;

    if (globex_ilink3_show_structs) {
        group = proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_ilink3_related_sym_groups_v83, &item, "Related Sym Groups");
    }

    unsigned start = offset;

    offset = dissect_globex_ilink3_group_size(tvb, pinfo, group, offset);

    /* Related Sym Group: Num In Group entries */
    uint32_t num_in_group = tvb_get_uint8(tvb, start + 2);

    for (uint32_t index = 0; index < num_in_group; index++) {
        offset = dissect_globex_ilink3_related_sym_group_v83(tvb, pinfo, group, offset, index + 1);
    }

    proto_item_set_len(item, offset - start);

    return offset;
}

/* Related Sym Group */
static unsigned
dissect_globex_ilink3_related_sym_group_v83(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, unsigned offset, uint32_t index)
{
    proto_item *item = NULL;
    proto_tree *group = tree;

    if (globex_ilink3_show_structs) {
        group = globex_ilink3_pref_show_indexes
            ? proto_tree_add_subtree_format(tree, tvb, offset, -1, ett_globex_ilink3_related_sym_group_v83, &item, "Related Sym Group %u", index)
            : proto_tree_add_subtree(tree, tvb, offset, -1, ett_globex_ilink3_related_sym_group_v83, &item, "Related Sym Group");
    }

    unsigned start = offset;

    offset = parse_globex_ilink3_security_id(tvb, pinfo, group, offset);
    offset = parse_globex_ilink3_order_qty_optional(tvb, pinfo, group, offset);
    offset = parse_globex_ilink3_rfq_side_v83(tvb, pinfo, group, offset);

    proto_item_set_len(item, offset - start);

    return offset;
}

