        return dissect_globex_ilink3_retransmission(tvb, pinfo, tree, offset);
    case GLOBEX_ILINK3_TEMPLATE_ID_RETRANSMIT_REJECT:
        return dissect_globex_ilink3_retransmit_reject(tvb, pinfo, tree, offset);
    case GLOBEX_ILINK3_TEMPLATE_ID_NOT_APPLIED:
