void
proto_reg_handoff_globex_ilink3(void)
{
    heur_dissector_add("tcp", dissect_globex_ilink3_heur, "Cme iLink3 over TCP",
        "globex_ilink3_tcp", proto_globex_ilink3, HEURISTIC_ENABLE);

    dissector_add_for_decode_as("tcp.port", globex_ilink3_handle);
}
